package com.atlasiq.security;
import com.atlasiq.qir.Finding;import jakarta.enterprise.context.ApplicationScoped;import java.nio.file.*;import java.util.*;import java.util.stream.Stream;
@ApplicationScoped public class IacSecurityScanner {public List<Finding> scan(Path root){List<Finding> out=new ArrayList<>();try(Stream<Path>s=Files.walk(root,8)){s.filter(Files::isRegularFile).forEach(p->{try{String x=Files.readString(p);String f=root.relativize(p).toString();if(f.endsWith(".tf")&&x.contains("0.0.0.0/0"))out.add(new Finding("iac:"+f+":public-network","high","security",f,"Public network exposure in Terraform","Restrict public ingress and avoid 0.0.0.0/0 where possible."));if((f.endsWith(".yaml")||f.endsWith(".yml"))&&x.contains("privileged: true"))out.add(new Finding("iac:"+f+":privileged-container","critical","security",f,"Privileged Kubernetes container","Run containers without privileged mode unless strictly required."));if((f.endsWith(".yaml")||f.endsWith(".yml"))&&x.contains("runAsUser: 0"))out.add(new Finding("iac:"+f+":runs-as-root","high","security",f,"Kubernetes workload runs as root","Set a non-root runAsUser and enforce pod security defaults."));}catch(Exception ignored){}});}catch(Exception ignored){}return List.copyOf(out);}}
